14	/** @return list<int> the account's planets (moons excluded) whose built defence columns are all zero */
15	function newbornColonyBarePlanets(int $playerId): array
16	{
17	    $defence = array_map(static fn ($object): string => $object->machine_name, ObjectService::getDefenseObjects());
18	
19	    return Planet::query()->where('user_id', $playerId)->where('planet_type', 1)->pluck('id')
20	        ->map(static fn ($id): int => (int) $id)
21	        ->filter(static function (int $id) use ($defence): bool {
22	            $planet = app(PlanetServiceFactory::class)->make($id, true);
23	            if ($planet === null) {
24	                return true;
25	            }
26	
27	            foreach ($defence as $machineName) {
28	                if ($planet->getDefenseUnits()->getAmountByMachineName($machineName) > 0) {
29	                    return false;
30	                }
31	            }
32	
33	            return true;
34	        })->values()->all();
35	}
36	
37	// PERS-004 (invariant:NAKED_BESIDE_WALLED, aspect:shipyard): the cohort read keeps finding an account
38	// with a planet at zero defence while a sibling holds a real wall (player 60: 2 planets at zero while
39	// one held 1,312 units). A newly founded colony is that planet: it is founded bare, with no yard and
40	// almost no stock, beside a homeworld that already stands a wall. What it earns it spends on the mine
41	// its own economy wants, so the wall's price is never reached at the instant a login plans, and the
42	// colony stays naked for as long as the account plays. This story follows such a colony for a day of
43	// the account's own logins and reads the cohort's invariant on it.
44	test('a walled homeworld reaches the newborn colony it founded bare', function (): void {
45	    $before = Planet::query()->where('user_id', $this->currentUserId)->pluck('id')->all();
46	
47	    $situation = Situation::of($this)
48	        ->level('robot_factory', 2)
49	        ->level('shipyard', 4)
50	        ->defence('rocket_launcher', 1_300)
51	        ->colony()
52	        ->day();
53	
54	    $colonyId = (int) Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)
55	        ->whereNotIn('id', $before)->value('id');
56	    $colony = app(PlanetServiceFactory::class)->make($colonyId, true);
57	
58	    expect(app(DefenseNeedEvaluator::class)->standingUnits($colony))->toBeGreaterThan(0, 'the newborn colony stayed at zero defence; ' . $situation->account())
59	        ->and(newbornColonyBarePlanets($this->currentUserId))->toBe([], 'planets at zero built defence: these; ' . $situation->account());
60	});

