    1	<?php
    2	
    3	use Illuminate\Support\Facades\DB;
    4	use Modules\AI\Domain\Decision\DefenseNeed;
    5	use Modules\AI\Domain\Decision\DefenseNeedEvaluator;
    6	use Modules\AI\Enums\AiWorkKind;
    7	use Modules\AI\Tests\Support\Situation;
    8	use OGame\Factories\PlanetServiceFactory;
    9	use OGame\Models\BuildingQueue;
   10	use OGame\Models\Planet;
   11	use OGame\Services\ObjectService;
   12	use OGame\Services\SettingsService;
   13	use Tests\IsolatedAccountTestCase;
   14	
   15	require_once __DIR__ . '/../../Support/Situation.php';
   16	
   17	uses(IsolatedAccountTestCase::class);
   18	
   19	// The one surviving situation for invariant:NAKED_BESIDE_WALLED after the QUAL-DEDUP merge: a naked
   20	// colony, a naked planet and a stationary fleet, each read at the bound and at zero. The live read
   21	// found accounts with planets at zero defence while a sibling held a real wall: the whole wall was
   22	// raised on the planet with the most to lose and the bare siblings were never reached.
   23	test('a login gives the bare sibling the wall the account already holds elsewhere', function (): void {
   24	    $situation = Situation::of($this)
   25	        ->levelEveryPlanet('robot_factory', 2)
   26	        ->levelEveryPlanet('shipyard', 4)
   27	        ->defence('rocket_launcher', 20)
   28	        ->stockEveryPlanet(20_000_000, 10_000_000, 5_000_000)
   29	        ->session();
   30	
   31	    $bare = Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)
   32	        ->whereKeyNot($this->currentPlanetId)->value('id');
   33	    $planet = app(PlanetServiceFactory::class)->make((int) $bare, true);
   34	
   35	    $situation->expectWork(AiWorkKind::QueueUnits);
   36	
   37	    // A short build may already be complete by the time the session's own clock has advanced to every
   38	    // intent, so the wall counts whether it is standing or still paid for in the yard.
   39	    expect(app(DefenseNeedEvaluator::class)->standingUnits($planet))->toBeGreaterThan(0, 'expected the wall on the bare sibling; ' . $situation->account());
   40	});
   41	
   42	// QUAL-003's live shape (invariant:NAKED_BESIDE_WALLED, aspect:shipyard), the story the deleted
   43	// NakedColonyWallSituationTest held: the colony below the yard its wall waits on. The cohort read
   44	// found an account holding a wall on one planet while a young colony stood at zero defence: the wall
   45	// waits on a shipyard the colony does not have yet, and the account kept spending its yard elsewhere.
   46	// An account whose sibling already holds a wall has to bring the shipyard and then the wall to the
   47	// bare colony, instead of leaving it naked for as long as it plays.
   48	test('an account whose sibling holds a wall reaches the colony that has no shipyard yet', function (): void {
   49	    $before = Planet::query()->where('user_id', $this->currentUserId)->pluck('id')->all();
   50	
   51	    $situation = Situation::of($this)
   52	        ->level('robot_factory', 2)
   53	        ->level('shipyard', 4)
   54	        ->defence('rocket_launcher', 30)
   55	        ->colony()
   56	        ->stockEveryPlanet(20_000_000, 10_000_000, 5_000_000)
   57	        ->sessions(8, 30);
   58	
   59	    $colonyId = (int) Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)
   60	        ->whereNotIn('id', $before)->value('id');
   61	    $colony = app(PlanetServiceFactory::class)->make($colonyId, true);
   62	
   63	    expect(app(DefenseNeedEvaluator::class)->standingUnits($colony))->toBeGreaterThan(0, 'expected the wall on the colony that started without a shipyard; ' . $situation->account());
   64	});
   65	
   66	// The story the deleted StationaryFleetWallSituationTest held: what a planet stands to lose is not only
   67	// the output that piles up while the account is away. A fleet left standing in orbit is worth to a
   68	// raider exactly what the pile is, so a wall sized on production alone leaves it uncovered. The plant
   69	// puts the idle fleet on a planet whose small wall already covers the mines, and the record must state
   70	// a need only once the fleet is there.
   71	test('an idle fleet raises what the planet stands to lose', function (): void {
   72	    $situation = Situation::of($this)
   73	        ->resources(1_000_000, 1_000_000, 1_000_000)
   74	        ->level('shipyard', 4)
   75	        ->defence('rocket_launcher', 200);
   76	
   77	    $player = $this->planetService->getPlayer();
   78	    $covered = app(DefenseNeedEvaluator::class)->evaluate($player, $this->planetService);
   79	
   80	    expect($covered)->toBeNull('the wall already covers production-only exposure; ' . $situation->account());
   81	
   82	    $situation->ships('light_fighter', 2_000);
   83	
   84	    $exposed = app(DefenseNeedEvaluator::class)->evaluate($player, $this->planetService);
   85	
   86	    expect($exposed)->toBeInstanceOf(DefenseNeed::class)
   87	        ->and($exposed->protectedValue)->toBeGreaterThan(0.0)
   88	        ->and($exposed->currentDefenseValue)->toBeGreaterThan(0.0);
   89	});
   90	
   91	// The bound at zero of the fleet rule: the fleet only adds to the exposure, it is not what creates the
   92	// need. A planet whose own output is nothing still takes the file's floor, so an account is not left
   93	// naked because it has no fleet to protect.
   94	test('a planet with nothing standing in orbit still takes the doctrine floor', function (): void {
   95	    resolve(SettingsService::class)->set('economy_speed', 1);
   96	
   97	    Situation::of($this)
   98	        ->resources(1_000_000, 1_000_000, 1_000_000)
   99	        ->level('shipyard', 4)
  100	        ->level('metal_mine', 0)
  101	        ->level('crystal_mine', 0)
  102	        ->level('deuterium_synthesizer', 0);
  103	
  104	    $this->planetService->updateResourceProductionStats();
  105	
  106	    $need = app(DefenseNeedEvaluator::class)->evaluate($this->planetService->getPlayer(), $this->planetService);
  107	
  108	    expect($need)->toBeInstanceOf(DefenseNeed::class)
  109	        ->and($need->reason)->toBe('defense:need:minimum-deterrent');
  110	});
  111	
  112	// The bound on the other side: a planet that already holds a wall is not the account's next wall order,
  113	// so one login serves the bare sibling instead of stacking yet another batch on the walled planet.
  114	test('a login does not spend its wall order on the planet that already holds one', function (): void {
  115	    $situation = Situation::of($this)
  116	        ->levelEveryPlanet('robot_factory', 2)
  117	        ->levelEveryPlanet('shipyard', 4)
  118	        ->defence('rocket_launcher', 20)
  119	        ->stockEveryPlanet(20_000_000, 10_000_000, 5_000_000)
  120	        ->session();
  121	
  122	    $home = app(PlanetServiceFactory::class)->make($this->currentPlanetId, true);
  123	    $situation->expectWork(AiWorkKind::QueueUnits);
  124	
  125	    expect(app(DefenseNeedEvaluator::class)->standingUnits($home))->toBe(20, 'expected the walled planet untouched while its sibling is bare; ' . $situation->account());
  126	});
  127	
  128	// The invariant counts the account, not the planet (player 51: one planet holding 1,496 units, others
  129	// naked), so a full day of the account's own logins must leave no sibling at zero defence.
  130	test('an account whose homeworld holds a wall leaves no sibling naked', function (): void {
  131	    $situation = Situation::of($this)
  132	        ->resources(50_000_000, 50_000_000, 50_000_000)
  133	        ->level('robot_factory', 2)
  134	        ->level('shipyard', 4)
  135	        ->ships('small_cargo', 10)
  136	        ->ships('light_laser', 60)
  137	        ->colony()
  138	        ->stockEveryPlanet(50_000_000, 50_000_000, 50_000_000);
  139	
  140	    $situation->day();
  141	
  142	    expect(nakedPlanets($this->currentUserId))->toBe([], 'these planets stay at zero defence; ' . $situation->account());
  143	});
  144	
  145	// A walled homeworld moves the bare sibling before the sibling's own habits, so one login already
  146	// turns to the yard the sibling needs rather than leaving it for a later day. The sibling's yard is
  147	// below the wall's unit, so the order it takes is the facility the wall waits on.
  148	test('a login beside a walled homeworld turns to the bare sibling', function (): void {
  149	    $situation = Situation::of($this)
  150	        ->resources(50_000_000, 50_000_000, 50_000_000)
  151	        ->level('robot_factory', 2)
  152	        ->level('shipyard', 4)
  153	        ->ships('small_cargo', 10)
  154	        ->ships('light_laser', 60)
  155	        ->colony()
  156	        ->stockEveryPlanet(50_000_000, 50_000_000, 50_000_000);
  157	
  158	    $situation->session();
  159	
  160	    foreach (nakedPlanets($this->currentUserId) as $planetId) {
  161	        $ordered = BuildingQueue::query()->where('planet_id', $planetId)->where('canceled', 0)->exists();
  162	        expect($ordered)->toBeTrue('the bare sibling got no order this login; ' . $situation->account());
  163	    }
  164	});
  165	
  166	// The zero case of the rule: the invariant names a naked planet *beside a walled sibling*. A lone
  167	// planet has no sibling, so nothing hoists the wall for it -- it takes the ordinary floor.
  168	test('a one-planet account is walled without a sibling to point at', function (): void {
  169	    $situation = Situation::of($this)
  170	        ->resources(50_000_000, 50_000_000, 50_000_000)
  171	        ->level('robot_factory', 2)
  172	        ->level('shipyard', 4)
  173	        ->ships('small_cargo', 10)
  174	        ->stockEveryPlanet(50_000_000, 50_000_000, 50_000_000);
  175	
  176	    $situation->day();
  177	
  178	    expect(standingDefence($this->currentUserId))->toBeGreaterThan(0, 'the lone planet stayed at zero defence; ' . $situation->account());
  179	});
  180	
  181	// The bound at zero: with nothing to build with, the account queues no wall at all -- the host's own
  182	// affordability gate is not bypassed to make a naked planet look walled. Read after the merged
  183	// stories, so one file carries the rule at the bound, at zero and past it.
  184	test('an account that can pay for nothing queues no wall', function (): void {
  185	    $situation = Situation::of($this)
  186	        ->level('robot_factory', 2)
  187	        ->level('shipyard', 4)
  188	        ->ships('small_cargo', 10)
  189	        ->ships('light_laser', 60)
  190	        ->colony();
  191	
  192	    $situation->session();
  193	
  194	    $defence = array_map(static fn ($object): string => $object->machine_name, ObjectService::getDefenseObjects());
  195	
  196	    expect($situation->work())->not->toBeEmpty()
  197	        ->and(array_intersect($defence, $situation->queued()))->toBe([], 'a wall was queued without the resources to pay for it; ' . $situation->account());
  198	});
  199	
  200	// The cohort's own read, the story the deleted NakedPlanetLiveInvariantTest held: the invariant counts
  201	// the defence columns the host has *built* on every planet and cries wolf when one is zero while a
  202	// sibling already holds a real wall. This mirrors that read after a full day of the account's own
  203	// logins, so the merged file proves the shape the live invariant actually measures, not only the
  204	// orders a login placed.
  205	test('a walled homeworld leaves no colony at zero built defence after a day', function (): void {
  206	    $situation = Situation::of($this)
  207	        ->resources(50_000_000, 50_000_000, 50_000_000)
  208	        ->level('robot_factory', 2)
  209	        ->level('shipyard', 4)
  210	        ->ships('small_cargo', 10)
  211	        ->defence('rocket_launcher', 1_200)
