403	     *
404	     * A resource the price does not spend keeps no floor: the floor is what must survive spending that
405	     * resource, so a purchase that costs no deuterium is not blocked by a deuterium reserve (SP5 --
406	     * saving for a drive must not freeze surplus metal and crystal).
407	     */
408	    private function withReserve(PlanetService $planet, Resources $price, float $savingHours): Resources
409	    {
410	        $floor = $this->reserveFloor->floor($planet, $savingHours);
411	
412	        return new Resources(
413	            $price->metal->get() > 0 ? $price->metal->get() + $floor->metal->get() : 0,
414	            $price->crystal->get() > 0 ? $price->crystal->get() + $floor->crystal->get() : 0,
415	            $price->deuterium->get() > 0 ? $price->deuterium->get() + $floor->deuterium->get() : 0,
416	            $price->energy->get(),
417	        );
418	    }
419	}

